@import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@400;500;600;700&family=Inter:wght@300;400;500;600;700&display=swap');

:root {
  --color-primary: #0A1628;
  --color-primary-light: #132240;
  --color-secondary: #003F2D;
  --color-accent: #C5A55A;
  --color-accent-hover: #B8963F;
  --color-white: #FFFFFF;
  --color-gray-50: #F8FAFC;
  --color-gray-100: #F1F5F9;
  --color-gray-200: #E2E8F0;
  --color-gray-300: #CBD5E1;
  --color-gray-400: #94A3B8;
  --color-gray-500: #64748B;
  --color-gray-600: #475569;
  --color-gray-700: #334155;
  --color-gray-800: #1E293B;
  --color-gray-900: #0F172A;
  --color-teal: #0D9488;
  --color-teal-dark: #0F766E;

  --font-heading: 'Cinzel', Georgia, serif;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;

  --max-width: 1280px;
  --header-height: 80px;

  --shadow-sm: 0 1px 2px rgba(10,22,40,0.05);
  --shadow-md: 0 4px 12px rgba(10,22,40,0.08);
  --shadow-lg: 0 8px 30px rgba(10,22,40,0.12);
  --shadow-xl: 0 20px 50px rgba(10,22,40,0.15);

  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;
}

*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-body);
  color: var(--color-gray-800);
  background: var(--color-white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

ul, ol { list-style: none; }

h1, h2, h3, h4, h5 {
  font-family: var(--font-heading);
  color: var(--color-primary);
  line-height: 1.2;
  font-weight: 600;
}

h1 { font-size: clamp(2rem, 4vw, 3.25rem); }
h2 { font-size: clamp(1.5rem, 3vw, 2.5rem); }
h3 { font-size: clamp(1.125rem, 2vw, 1.5rem); }
h4 { font-size: 1.125rem; }

p { max-width: 72ch; }

.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

@media (min-width: 768px) {
  .container { padding: 0 40px; }
}

@media (min-width: 1024px) {
  .container { padding: 0 48px; }
}

/* ─── BUTTONS ──────────────────────────────── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 32px;
  font-family: var(--font-body);
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  border: none;
  border-radius: 2px;
  cursor: pointer;
  transition: all var(--transition-base);
  white-space: nowrap;
  min-height: 48px;
}

.btn-primary {
  background: var(--color-accent);
  color: var(--color-primary);
}
.btn-primary:hover {
  background: var(--color-accent-hover);
  box-shadow: var(--shadow-md);
}

.btn-outline {
  background: transparent;
  color: var(--color-white);
  border: 2px solid var(--color-white);
}
.btn-outline:hover {
  background: var(--color-white);
  color: var(--color-primary);
}

.btn-outline-dark {
  background: transparent;
  color: var(--color-primary);
  border: 2px solid var(--color-primary);
}
.btn-outline-dark:hover {
  background: var(--color-primary);
  color: var(--color-white);
}

.btn-ghost {
  background: transparent;
  color: var(--color-accent);
  padding: 8px 0;
  letter-spacing: 0.02em;
}
.btn-ghost:hover { color: var(--color-accent-hover); }
.btn-ghost .arrow { transition: transform var(--transition-fast); }
.btn-ghost:hover .arrow { transform: translateX(4px); }

/* ─── HEADER ──────────────────────────────── */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: var(--color-primary);
  height: var(--header-height);
  transition: background var(--transition-base), box-shadow var(--transition-base);
}

.site-header.scrolled {
  background: rgba(10,22,40,0.97);
  box-shadow: var(--shadow-lg);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

@media (min-width: 768px) {
  .header-inner { padding: 0 40px; }
}

.logo {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-white);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  display: flex;
  align-items: center;
  gap: 10px;
}

.logo-icon {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.logo-icon svg {
  width: 100%;
  height: 100%;
}

/* ── Desktop Nav ── */
.main-nav {
  display: none;
  align-items: center;
  gap: 0;
  height: 100%;
}

@media (min-width: 1024px) {
  .main-nav { display: flex; }
}

.nav-link {
  display: flex;
  align-items: center;
  gap: 4px;
  height: 100%;
  padding: 0 20px;
  color: rgba(255,255,255,0.85);
  font-size: 0.9rem;
  font-weight: 500;
  transition: color var(--transition-fast);
  cursor: pointer;
  position: relative;
}

.nav-link:hover,
.nav-link.active {
  color: var(--color-white);
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 20px;
  right: 20px;
  height: 3px;
  background: var(--color-accent);
  transform: scaleX(0);
  transition: transform var(--transition-base);
}

.nav-link:hover::after,
.nav-link.active::after {
  transform: scaleX(1);
}

.nav-link .chevron {
  width: 12px;
  height: 12px;
  transition: transform var(--transition-fast);
}

.nav-link:hover .chevron,
.nav-link.active .chevron {
  transform: rotate(180deg);
}

/* ── Mega Menu ── */
.mega-menu {
  position: absolute;
  top: var(--header-height);
  left: 0;
  right: 0;
  background: var(--color-white);
  box-shadow: var(--shadow-xl);
  opacity: 0;
  visibility: hidden;
  transform: translateY(-8px);
  transition: opacity var(--transition-base), visibility var(--transition-base), transform var(--transition-base);
  z-index: 999;
}

.mega-menu.open {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.mega-menu-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 48px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
}

.mega-menu-col h4 {
  font-family: var(--font-body);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--color-gray-400);
  margin-bottom: 20px;
}

.mega-menu-links {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.mega-menu-links a {
  display: block;
  padding: 10px 16px;
  color: var(--color-gray-700);
  font-size: 0.95rem;
  font-weight: 500;
  border-radius: 6px;
  transition: all var(--transition-fast);
}

.mega-menu-links a:hover {
  background: var(--color-gray-50);
  color: var(--color-secondary);
}

/* ── Mobile Nav ── */
.mobile-toggle {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
  background: none;
  border: none;
  cursor: pointer;
  min-width: 44px;
  min-height: 44px;
  align-items: center;
  justify-content: center;
}

@media (min-width: 1024px) {
  .mobile-toggle { display: none; }
}

.mobile-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--color-white);
  border-radius: 2px;
  transition: all var(--transition-base);
}

.mobile-toggle.active span:nth-child(1) {
  transform: translateY(7px) rotate(45deg);
}
.mobile-toggle.active span:nth-child(2) {
  opacity: 0;
}
.mobile-toggle.active span:nth-child(3) {
  transform: translateY(-7px) rotate(-45deg);
}

.mobile-nav {
  position: fixed;
  top: var(--header-height);
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--color-primary);
  z-index: 998;
  overflow-y: auto;
  transform: translateX(100%);
  transition: transform var(--transition-slow);
}

.mobile-nav.open {
  transform: translateX(0);
}

.mobile-nav-links {
  padding: 24px;
}

.mobile-nav-link {
  display: block;
  padding: 16px 0;
  color: rgba(255,255,255,0.85);
  font-size: 1.1rem;
  font-weight: 500;
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

.mobile-accordion-btn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 16px 0;
  background: none;
  border: none;
  border-bottom: 1px solid rgba(255,255,255,0.1);
  color: rgba(255,255,255,0.85);
  font-family: var(--font-body);
  font-size: 1.1rem;
  font-weight: 500;
  cursor: pointer;
  min-height: 56px;
}

.mobile-accordion-btn .chevron-mobile {
  width: 16px;
  height: 16px;
  transition: transform var(--transition-fast);
  color: var(--color-accent);
}

.mobile-accordion-btn.active .chevron-mobile {
  transform: rotate(180deg);
}

.mobile-accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow);
}

.mobile-accordion-content.open {
  max-height: 600px;
}

.mobile-accordion-content a {
  display: block;
  padding: 12px 24px;
  color: rgba(255,255,255,0.65);
  font-size: 0.95rem;
  border-bottom: 1px solid rgba(255,255,255,0.05);
  transition: color var(--transition-fast);
}

.mobile-accordion-content a:hover {
  color: var(--color-accent);
}

.mobile-accordion-label {
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--color-gray-400);
  padding: 16px 24px 8px;
}

/* ─── HERO ──────────────────────────────── */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-light) 50%, var(--color-secondary) 100%);
  overflow: hidden;
  padding-top: var(--header-height);
}

.hero-bg {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
  opacity: 0.25;
}

.hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(10,22,40,0.85) 0%, rgba(0,63,45,0.7) 100%);
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 680px;
  padding: 80px 0;
}

.hero-eyebrow {
  font-family: var(--font-body);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  color: var(--color-accent);
  margin-bottom: 24px;
}

.hero h1 {
  color: var(--color-white);
  margin-bottom: 24px;
  font-size: clamp(2.25rem, 5vw, 3.5rem);
}

.hero p {
  color: rgba(255,255,255,0.8);
  font-size: 1.125rem;
  line-height: 1.7;
  margin-bottom: 40px;
  max-width: 540px;
}

.hero-pattern {
  position: absolute;
  right: -100px;
  bottom: -100px;
  width: 500px;
  height: 500px;
  border: 1px solid rgba(197,165,90,0.1);
  border-radius: 50%;
}

.hero-pattern::before {
  content: '';
  position: absolute;
  top: 40px;
  left: 40px;
  right: 40px;
  bottom: 40px;
  border: 1px solid rgba(197,165,90,0.07);
  border-radius: 50%;
}

/* ── Page Hero (smaller variant) ── */
.hero-page {
  min-height: 50vh;
  padding-top: var(--header-height);
}

.hero-page .hero-content {
  padding: 60px 0;
}

/* ─── SECTIONS ──────────────────────────── */
.section {
  padding: 96px 0;
}

.section-sm {
  padding: 64px 0;
}

.section-dark {
  background: var(--color-primary);
  color: var(--color-white);
}

.section-dark h2,
.section-dark h3,
.section-dark h4 {
  color: var(--color-white);
}

.section-light {
  background: var(--color-gray-50);
}

.section-header {
  margin-bottom: 56px;
}

.section-header h2 {
  margin-bottom: 16px;
}

.section-header p {
  color: var(--color-gray-500);
  font-size: 1.0625rem;
  line-height: 1.7;
}

.section-eyebrow {
  font-family: var(--font-body);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  color: var(--color-accent);
  margin-bottom: 12px;
}

/* ─── FEATURED INSIGHTS ──────────────── */
.insights-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}

@media (min-width: 768px) {
  .insights-grid { grid-template-columns: repeat(3, 1fr); }
}

.insight-card {
  background: var(--color-white);
  border-radius: 4px;
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-base);
}

.insight-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.insight-card-img {
  height: 200px;
  background: linear-gradient(135deg, var(--color-primary-light), var(--color-secondary));
  position: relative;
  overflow: hidden;
}

.insight-card-img::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(45deg, rgba(197,165,90,0.15), transparent);
}

.insight-card-body {
  padding: 24px;
}

.insight-tag {
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-teal);
  margin-bottom: 12px;
}

.insight-card-body h3 {
  font-size: 1.0625rem;
  line-height: 1.4;
  margin-bottom: 12px;
}

.insight-date {
  font-size: 0.8125rem;
  color: var(--color-gray-400);
}

/* ─── ANNOUNCEMENT BANNER ────────────── */
.announcement-banner {
  background: var(--color-secondary);
  padding: 20px 0;
}

.announcement-inner {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 24px;
  flex-wrap: wrap;
  text-align: center;
}

.announcement-inner p {
  color: var(--color-white);
  font-size: 1rem;
  font-weight: 500;
}

.announcement-inner .btn-ghost {
  color: var(--color-accent);
}

/* ─── ABOUT STATEMENT ────────────────── */
.about-statement {
  display: grid;
  grid-template-columns: 1fr;
  gap: 48px;
  align-items: center;
}

@media (min-width: 768px) {
  .about-statement {
    grid-template-columns: 1fr 1fr;
    gap: 80px;
  }
}

.about-visual {
  position: relative;
  height: 400px;
  border-radius: 4px;
  overflow: hidden;
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-secondary) 100%);
}

.about-visual-overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 32px;
  background: linear-gradient(transparent, rgba(10,22,40,0.9));
}

.about-visual-stat {
  color: var(--color-white);
}

.about-visual-stat .number {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--color-accent);
  display: block;
}

.about-visual-stat .label {
  font-size: 0.875rem;
  opacity: 0.8;
}

.about-text h2 {
  margin-bottom: 24px;
}

.about-text p {
  color: var(--color-gray-600);
  margin-bottom: 32px;
  line-height: 1.8;
}

/* ─── WHAT WE DO (TABS) ─────────────── */
.what-we-do {
  background: var(--color-primary);
  padding: 96px 0;
}

.wwd-layout {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0;
}

@media (min-width: 768px) {
  .wwd-layout {
    grid-template-columns: 280px 1fr;
    gap: 0;
  }
}

.wwd-tabs {
  display: flex;
  flex-direction: row;
  overflow-x: auto;
}

@media (min-width: 768px) {
  .wwd-tabs {
    flex-direction: column;
    overflow-x: visible;
    border-right: 1px solid rgba(255,255,255,0.1);
  }
}

.wwd-tab {
  padding: 20px 24px;
  background: none;
  border: none;
  color: rgba(255,255,255,0.5);
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 500;
  cursor: pointer;
  text-align: left;
  transition: all var(--transition-base);
  white-space: nowrap;
  position: relative;
  min-height: 48px;
}

@media (min-width: 768px) {
  .wwd-tab {
    padding: 28px 32px;
    font-size: 1.125rem;
  }
}

.wwd-tab::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 24px;
  right: 24px;
  height: 3px;
  background: var(--color-accent);
  transform: scaleX(0);
  transition: transform var(--transition-base);
}

@media (min-width: 768px) {
  .wwd-tab::after {
    top: 0;
    bottom: 0;
    left: auto;
    right: 0;
    width: 3px;
    height: auto;
    transform: scaleY(0);
  }
}

.wwd-tab.active {
  color: var(--color-white);
}

.wwd-tab.active::after {
  transform: scaleX(1);
}

@media (min-width: 768px) {
  .wwd-tab.active::after {
    transform: scaleY(1);
  }
}

.wwd-tab:hover {
  color: rgba(255,255,255,0.8);
}

.wwd-panels {
  position: relative;
  min-height: 250px;
}

.wwd-panel {
  display: none;
  padding: 32px 24px;
}

@media (min-width: 768px) {
  .wwd-panel {
    padding: 32px 48px;
  }
}

.wwd-panel.active {
  display: block;
  animation: panelFade 0.35s ease;
}

@keyframes panelFade {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

.wwd-panel h3 {
  color: var(--color-white);
  font-size: 1.75rem;
  margin-bottom: 20px;
}

.wwd-panel p {
  color: rgba(255,255,255,0.7);
  font-size: 1.0625rem;
  line-height: 1.8;
  margin-bottom: 32px;
  max-width: 560px;
}

.wwd-panel .service-list {
  margin-bottom: 32px;
}

.wwd-panel .service-list li {
  color: rgba(255,255,255,0.7);
  padding: 8px 0;
  padding-left: 20px;
  position: relative;
  font-size: 0.95rem;
}

.wwd-panel .service-list li::before {
  content: '';
  position: absolute;
  left: 0;
  top: 16px;
  width: 6px;
  height: 6px;
  background: var(--color-accent);
  border-radius: 50%;
}

.wwd-panel .btn-primary {
  margin-top: 8px;
}

/* ─── NEWSLETTER ─────────────────────── */
.newsletter {
  background: linear-gradient(135deg, var(--color-secondary) 0%, var(--color-primary) 100%);
  padding: 80px 0;
  text-align: center;
}

.newsletter h2 {
  color: var(--color-white);
  margin-bottom: 12px;
}

.newsletter p {
  color: rgba(255,255,255,0.7);
  margin: 0 auto 32px;
  max-width: 480px;
}

.newsletter-form {
  display: flex;
  flex-direction: column;
  gap: 12px;
  max-width: 440px;
  margin: 0 auto;
}

@media (min-width: 480px) {
  .newsletter-form {
    flex-direction: row;
  }
}

.newsletter-form input {
  flex: 1;
  padding: 14px 20px;
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: 2px;
  background: rgba(255,255,255,0.1);
  color: var(--color-white);
  font-family: var(--font-body);
  font-size: 0.9375rem;
  min-height: 48px;
}

.newsletter-form input::placeholder {
  color: rgba(255,255,255,0.5);
}

.newsletter-form input:focus {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

/* ─── COMMITMENT PILLARS ─────────────── */
.pillars-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}

@media (min-width: 768px) {
  .pillars-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .pillars-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

.pillar-card {
  padding: 32px;
  border: 1px solid var(--color-gray-200);
  border-radius: 4px;
  transition: all var(--transition-base);
}

.pillar-card:hover {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-md);
}

.pillar-icon {
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(197,165,90,0.1);
  border-radius: 8px;
  margin-bottom: 20px;
  color: var(--color-accent);
}

.pillar-card h3 {
  font-size: 1.125rem;
  margin-bottom: 12px;
}

.pillar-card p {
  color: var(--color-gray-500);
  font-size: 0.9375rem;
  line-height: 1.7;
  margin-bottom: 20px;
}

/* ─── SERVICE CATEGORIES GRID ────────── */
.services-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 32px;
}

@media (min-width: 768px) {
  .services-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .services-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.service-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: 4px;
  padding: 40px 32px;
  transition: all var(--transition-base);
  display: flex;
  flex-direction: column;
}

.service-card:hover {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.service-card-icon {
  width: 56px;
  height: 56px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, var(--color-primary), var(--color-secondary));
  border-radius: 8px;
  margin-bottom: 24px;
  color: var(--color-accent);
}

.service-card h3 {
  font-size: 1.25rem;
  margin-bottom: 16px;
}

.service-card p {
  color: var(--color-gray-500);
  font-size: 0.9375rem;
  line-height: 1.7;
  margin-bottom: 24px;
  flex: 1;
}

/* ─── CAPABILITIES GRID ──────────────── */
.capabilities-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}

@media (min-width: 768px) {
  .capabilities-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .capabilities-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.capability-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: 4px;
  padding: 32px;
  transition: all var(--transition-base);
}

.capability-card:hover {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-md);
}

.capability-card h4 {
  font-family: var(--font-heading);
  font-size: 1.125rem;
  margin-bottom: 12px;
  color: var(--color-primary);
}

.capability-card p {
  color: var(--color-gray-500);
  font-size: 0.9375rem;
  line-height: 1.7;
}

.capability-card-accent {
  width: 40px;
  height: 3px;
  background: var(--color-accent);
  margin-bottom: 20px;
}

/* ─── FEATURED TOPICS ────────────────── */
.topics-list {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.topic-tag {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 24px;
  border: 1px solid var(--color-gray-200);
  border-radius: 4px;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-primary);
  transition: all var(--transition-base);
  cursor: pointer;
}

.topic-tag:hover {
  border-color: var(--color-accent);
  background: rgba(197,165,90,0.05);
  color: var(--color-accent);
}

/* ─── PARTNERSHIP HIGHLIGHT ──────────── */
.partnership {
  display: grid;
  grid-template-columns: 1fr;
  gap: 48px;
  align-items: center;
}

@media (min-width: 768px) {
  .partnership {
    grid-template-columns: 1fr 1fr;
    gap: 80px;
  }
}

.partnership-visual {
  height: 360px;
  background: linear-gradient(135deg, var(--color-primary), var(--color-secondary));
  border-radius: 4px;
  position: relative;
  overflow: hidden;
}

.partnership-stats {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  display: grid;
  grid-template-columns: 1fr 1fr;
}

.partnership-stat {
  padding: 24px;
  background: rgba(10,22,40,0.8);
  text-align: center;
}

.partnership-stat .number {
  font-family: var(--font-heading);
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--color-accent);
  display: block;
}

.partnership-stat .label {
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.7);
}

/* ─── TESTIMONIAL ────────────────────── */
.testimonial-block {
  background: var(--color-gray-50);
  border-left: 4px solid var(--color-accent);
  padding: 40px;
  border-radius: 0 4px 4px 0;
}

.testimonial-block blockquote {
  font-size: 1.125rem;
  line-height: 1.8;
  color: var(--color-gray-700);
  margin-bottom: 20px;
  font-style: italic;
}

.testimonial-block cite {
  font-style: normal;
  font-weight: 600;
  color: var(--color-primary);
  font-size: 0.9375rem;
}

/* ─── CAROUSEL ────────────────────────── */
.carousel-container {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform var(--transition-slow);
}

.carousel-slide {
  min-width: 100%;
  padding: 0 12px;
}

@media (min-width: 768px) {
  .carousel-slide { min-width: 50%; }
}

@media (min-width: 1024px) {
  .carousel-slide { min-width: 33.333%; }
}

.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-top: 32px;
}

.carousel-btn {
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 2px solid var(--color-gray-200);
  border-radius: 50%;
  background: var(--color-white);
  cursor: pointer;
  transition: all var(--transition-fast);
  color: var(--color-primary);
}

.carousel-btn:hover {
  border-color: var(--color-accent);
  color: var(--color-accent);
}

.carousel-dots {
  display: flex;
  gap: 8px;
}

.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-gray-300);
  border: none;
  cursor: pointer;
  transition: all var(--transition-fast);
  padding: 0;
}

.carousel-dot.active {
  background: var(--color-accent);
  width: 24px;
  border-radius: 4px;
}

/* ─── RELATED SERVICES ───────────────── */
.related-services-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 20px;
}

@media (min-width: 768px) {
  .related-services-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

.related-service-link {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 24px;
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: 4px;
  transition: all var(--transition-base);
}

.related-service-link:hover {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-md);
}

.related-service-link span {
  font-weight: 600;
  color: var(--color-primary);
}

.related-service-link .arrow-icon {
  color: var(--color-accent);
  transition: transform var(--transition-fast);
}

.related-service-link:hover .arrow-icon {
  transform: translateX(4px);
}

/* ─── PROPERTY TYPES CTA ─────────────── */
.property-types-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}

@media (min-width: 768px) {
  .property-types-grid {
    grid-template-columns: repeat(5, 1fr);
  }
}

.property-type-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  padding: 24px 16px;
  border: 1px solid var(--color-gray-200);
  border-radius: 4px;
  transition: all var(--transition-base);
  text-align: center;
  cursor: pointer;
}

.property-type-card:hover {
  border-color: var(--color-accent);
  background: rgba(197,165,90,0.03);
}

.property-type-icon {
  width: 44px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-secondary);
}

.property-type-card span {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-primary);
}

/* ─── DEAL FLOW CTA ──────────────────── */
.deal-flow-cta {
  background: linear-gradient(135deg, var(--color-primary), var(--color-secondary));
  border-radius: 4px;
  padding: 56px 48px;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 24px;
}

@media (min-width: 768px) {
  .deal-flow-cta {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }
}

.deal-flow-cta h3 {
  color: var(--color-white);
  font-size: 1.5rem;
}

.deal-flow-cta p {
  color: rgba(255,255,255,0.7);
  max-width: 480px;
}

/* ─── FOOTER ──────────────────────────── */
.site-footer {
  background: var(--color-gray-900);
  color: rgba(255,255,255,0.7);
  padding: 64px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 40px;
  margin-bottom: 48px;
}

@media (min-width: 768px) {
  .footer-grid {
    grid-template-columns: 2fr 1fr 1fr 1fr;
  }
}

.footer-brand .logo {
  margin-bottom: 16px;
  font-size: 1.125rem;
}

.footer-brand p {
  font-size: 0.875rem;
  line-height: 1.7;
  max-width: 300px;
}

.footer-col h4 {
  font-family: var(--font-body);
  font-size: 0.8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-white);
  margin-bottom: 20px;
}

.footer-col a {
  display: block;
  padding: 6px 0;
  font-size: 0.875rem;
  color: rgba(255,255,255,0.6);
  transition: color var(--transition-fast);
}

.footer-col a:hover {
  color: var(--color-accent);
}

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 24px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  align-items: center;
  text-align: center;
}

@media (min-width: 768px) {
  .footer-bottom {
    flex-direction: row;
    justify-content: space-between;
    text-align: left;
  }
}

.footer-bottom p {
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.4);
}

.footer-legal {
  display: flex;
  gap: 24px;
  flex-wrap: wrap;
}

.footer-legal a {
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.4);
  transition: color var(--transition-fast);
}

.footer-legal a:hover {
  color: var(--color-accent);
}

/* ─── UTILITIES ──────────────────────── */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  border: 0;
}

.text-accent { color: var(--color-accent); }
.text-white { color: var(--color-white); }
.bg-white { background: var(--color-white); }

@media (prefers-reduced-motion: reduce) {
  *,*::before,*::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
  html { scroll-behavior: auto; }
}

/* ─── SKIP LINK ──────────────────────── */
.skip-link {
  position: absolute;
  top: -100px;
  left: 16px;
  background: var(--color-accent);
  color: var(--color-primary);
  padding: 12px 24px;
  font-weight: 600;
  z-index: 10000;
  border-radius: 0 0 4px 4px;
  transition: top var(--transition-fast);
}

.skip-link:focus {
  top: 0;
}

@import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@400;500;600;700&family=Inter:wght@300;400;500;600;700&display=swap');

:root {
  --color-primary: #0A1628;
  --color-primary-light: #132240;
  --color-secondary: #003F2D;
  --color-accent: #C5A55A;
  --color-accent-hover: #B8963F;
  --color-white: #FFFFFF;
  --color-gray-50: #F8FAFC;
  --color-gray-100: #F1F5F9;
  --color-gray-200: #E2E8F0;
  --color-gray-300: #CBD5E1;
  --color-gray-400: #94A3B8;
  --color-gray-500: #64748B;
  --color-gray-600: #475569;
  --color-gray-700: #334155;
  --color-gray-800: #1E293B;
  --color-gray-900: #0F172A;
  --color-teal: #0D9488;
  --color-teal-dark: #0F766E;

  --font-heading: 'Cinzel', Georgia, serif;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;

  --max-width: 1280px;
  --header-height: 80px;

  --shadow-sm: 0 1px 2px rgba(10,22,40,0.05);
  --shadow-md: 0 4px 12px rgba(10,22,40,0.08);
  --shadow-lg: 0 8px 30px rgba(10,22,40,0.12);
  --shadow-xl: 0 20px 50px rgba(10,22,40,0.15);

  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;
}

*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-body);
  color: var(--color-gray-800);
  background: var(--color-white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

ul, ol { list-style: none; }

h1, h2, h3, h4, h5 {
  font-family: var(--font-heading);
  color: var(--color-primary);
  line-height: 1.2;
  font-weight: 600;
}

h1 { font-size: clamp(2rem, 4vw, 3.25rem); }
h2 { font-size: clamp(1.5rem, 3vw, 2.5rem); }
h3 { font-size: clamp(1.125rem, 2vw, 1.5rem); }
h4 { font-size: 1.125rem; }

p { max-width: 72ch; }

.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

@media (min-width: 768px) {
  .container { padding: 0 40px; }
}

@media (min-width: 1024px) {
  .container { padding: 0 48px; }
}

/* ─── BUTTONS ──────────────────────────────── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 32px;
  font-family: var(--font-body);
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  border: none;
  border-radius: 2px;
  cursor: pointer;
  transition: all var(--transition-base);
  white-space: nowrap;
  min-height: 48px;
}

.btn-primary {
  background: var(--color-accent);
  color: var(--color-primary);
}
.btn-primary:hover {
  background: var(--color-accent-hover);
  box-shadow: var(--shadow-md);
}

.btn-outline {
  background: transparent;
  color: var(--color-white);
  border: 2px solid var(--color-white);
}
.btn-outline:hover {
  background: var(--color-white);
  color: var(--color-primary);
}

.btn-outline-dark {
  background: transparent;
  color: var(--color-primary);
  border: 2px solid var(--color-primary);
}
.btn-outline-dark:hover {
  background: var(--color-primary);
  color: var(--color-white);
}

.btn-ghost {
  background: transparent;
  color: var(--color-accent);
  padding: 8px 0;
  letter-spacing: 0.02em;
}
.btn-ghost:hover { color: var(--color-accent-hover); }
.btn-ghost .arrow { transition: transform var(--transition-fast); }
.btn-ghost:hover .arrow { transform: translateX(4px); }

/* ─── HEADER ──────────────────────────────── */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: var(--color-primary);
  height: var(--header-height);
  transition: background var(--transition-base), box-shadow var(--transition-base);
}

.site-header.scrolled {
  background: rgba(10,22,40,0.97);
  box-shadow: var(--shadow-lg);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

@media (min-width: 768px) {
  .header-inner { padding: 0 40px; }
}

.logo {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-white);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  display: flex;
  align-items: center;
  gap: 10px;
}

.logo-icon {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.logo-icon svg {
  width: 100%;
  height: 100%;
}

/* ── Desktop Nav ── */
.main-nav {
  display: none;
  align-items: center;
  gap: 0;
  height: 100%;
}

@media (min-width: 1024px) {
  .main-nav { display: flex; }
}

.nav-link {
  display: flex;
  align-items: center;
  gap: 4px;
  height: 100%;
  padding: 0 20px;
  color: rgba(255,255,255,0.85);
  font-size: 0.9rem;
  font-weight: 500;
  transition: color var(--transition-fast);
  cursor: pointer;
  position: relative;
}

.nav-link:hover,
.nav-link.active {
  color: var(--color-white);
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 20px;
  right: 20px;
  height: 3px;
  background: var(--color-accent);
  transform: scaleX(0);
  transition: transform var(--transition-base);
}

.nav-link:hover::after,
.nav-link.active::after {
  transform: scaleX(1);
}

.nav-link .chevron {
  width: 12px;
  height: 12px;
  transition: transform var(--transition-fast);
}

.nav-link:hover .chevron,
.nav-link.active .chevron {
  transform: rotate(180deg);
}

/* ── Mega Menu ── */
.mega-menu {
  position: absolute;
  top: var(--header-height);
  left: 0;
  right: 0;
  background: var(--color-white);
  box-shadow: var(--shadow-xl);
  opacity: 0;
  visibility: hidden;
  transform: translateY(-8px);
  transition: opacity var(--transition-base), visibility var(--transition-base), transform var(--transition-base);
  z-index: 999;
}

.mega-menu.open {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.mega-menu-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 48px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
}

.mega-menu-col h4 {
  font-family: var(--font-body);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--color-gray-400);
  margin-bottom: 20px;
}

.mega-menu-links {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.mega-menu-links a {
  display: block;
  padding: 10px 16px;
  color: var(--color-gray-700);
  font-size: 0.95rem;
  font-weight: 500;
  border-radius: 6px;
  transition: all var(--transition-fast);
}

.mega-menu-links a:hover {
  background: var(--color-gray-50);
  color: var(--color-secondary);
}

/* ── Mobile Nav ── */
.mobile-toggle {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
  background: none;
  border: none;
  cursor: pointer;
  min-width: 44px;
  min-height: 44px;
  align-items: center;
  justify-content: center;
}

@media (min-width: 1024px) {
  .mobile-toggle { display: none; }
}

.mobile-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--color-white);
  border-radius: 2px;
  transition: all var(--transition-base);
}

.mobile-toggle.active span:nth-child(1) {
  transform: translateY(7px) rotate(45deg);
}
.mobile-toggle.active span:nth-child(2) {
  opacity: 0;
}
.mobile-toggle.active span:nth-child(3) {
  transform: translateY(-7px) rotate(-45deg);
}

.mobile-nav {
  position: fixed;
  top: var(--header-height);
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--color-primary);
  z-index: 998;
  overflow-y: auto;
  transform: translateX(100%);
  transition: transform var(--transition-slow);
}

.mobile-nav.open {
  transform: translateX(0);
}

.mobile-nav-links {
  padding: 24px;
}

.mobile-nav-link {
  display: block;
  padding: 16px 0;
  color: rgba(255,255,255,0.85);
  font-size: 1.1rem;
  font-weight: 500;
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

.mobile-accordion-btn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 16px 0;
  background: none;
  border: none;
  border-bottom: 1px solid rgba(255,255,255,0.1);
  color: rgba(255,255,255,0.85);
  font-family: var(--font-body);
  font-size: 1.1rem;
  font-weight: 500;
  cursor: pointer;
  min-height: 56px;
}

.mobile-accordion-btn .chevron-mobile {
  width: 16px;
  height: 16px;
  transition: transform var(--transition-fast);
  color: var(--color-accent);
}

.mobile-accordion-btn.active .chevron-mobile {
  transform: rotate(180deg);
}

.mobile-accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow);
}

.mobile-accordion-content.open {
  max-height: 600px;
}

.mobile-accordion-content a {
  display: block;
  padding: 12px 24px;
  color: rgba(255,255,255,0.65);
  font-size: 0.95rem;
  border-bottom: 1px solid rgba(255,255,255,0.05);
  transition: color var(--transition-fast);
}

.mobile-accordion-content a:hover {
  color: var(--color-accent);
}

.mobile-accordion-label {
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--color-gray-400);
  padding: 16px 24px 8px;
}

/* ─── HERO ──────────────────────────────── */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-light) 50%, var(--color-secondary) 100%);
  overflow: hidden;
  padding-top: var(--header-height);
}

.hero-bg {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
  opacity: 0.25;
}

.hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(10,22,40,0.85) 0%, rgba(0,63,45,0.7) 100%);
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 680px;
  padding: 80px 0;
}

.hero-eyebrow {
  font-family: var(--font-body);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  color: var(--color-accent);
  margin-bottom: 24px;
}

.hero h1 {
  color: var(--color-white);
  margin-bottom: 24px;
  font-size: clamp(2.25rem, 5vw, 3.5rem);
}

.hero p {
  color: rgba(255,255,255,0.8);
  font-size: 1.125rem;
  line-height: 1.7;
  margin-bottom: 40px;
  max-width: 540px;
}

.hero-pattern {
  position: absolute;
  right: -100px;
  bottom: -100px;
  width: 500px;
  height: 500px;
  border: 1px solid rgba(197,165,90,0.1);
  border-radius: 50%;
}

.hero-pattern::before {
  content: '';
  position: absolute;
  top: 40px;
  left: 40px;
  right: 40px;
  bottom: 40px;
  border: 1px solid rgba(197,165,90,0.07);
  border-radius: 50%;
}

/* ── Page Hero (smaller variant) ── */
.hero-page {
  min-height: 50vh;
  padding-top: var(--header-height);
}

.hero-page .hero-content {
  padding: 60px 0;
}

/* ─── SECTIONS ──────────────────────────── */
.section {
  padding: 96px 0;
}

.section-sm {
  padding: 64px 0;
}

.section-dark {
  background: var(--color-primary);
  color: var(--color-white);
}

.section-dark h2,
.section-dark h3,
.section-dark h4 {
  color: var(--color-white);
}

.section-light {
  background: var(--color-gray-50);
}

.section-header {
  margin-bottom: 56px;
}

.section-header h2 {
  margin-bottom: 16px;
}

.section-header p {
  color: var(--color-gray-500);
  font-size: 1.0625rem;
  line-height: 1.7;
}

.section-eyebrow {
  font-family: var(--font-body);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  color: var(--color-accent);
  margin-bottom: 12px;
}

/* ─── FEATURED INSIGHTS ──────────────── */
.insights-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}

@media (min-width: 768px) {
  .insights-grid { grid-template-columns: repeat(3, 1fr); }
}

.insight-card {
  background: var(--color-white);
  border-radius: 4px;
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-base);
}

.insight-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.insight-card-img {
  height: 200px;
  background: linear-gradient(135deg, var(--color-primary-light), var(--color-secondary));
  position: relative;
  overflow: hidden;
}

.insight-card-img::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(45deg, rgba(197,165,90,0.15), transparent);
}

.insight-card-body {
  padding: 24px;
}

.insight-tag {
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-teal);
  margin-bottom: 12px;
}

.insight-card-body h3 {
  font-size: 1.0625rem;
  line-height: 1.4;
  margin-bottom: 12px;
}

.insight-date {
  font-size: 0.8125rem;
  color: var(--color-gray-400);
}

/* ─── ANNOUNCEMENT BANNER ────────────── */
.announcement-banner {
  background: var(--color-secondary);
  padding: 20px 0;
}

.announcement-inner {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 24px;
  flex-wrap: wrap;
  text-align: center;
}

.announcement-inner p {
  color: var(--color-white);
  font-size: 1rem;
  font-weight: 500;
}

.announcement-inner .btn-ghost {
  color: var(--color-accent);
}

/* ─── ABOUT STATEMENT ────────────────── */
.about-statement {
  display: grid;
  grid-template-columns: 1fr;
  gap: 48px;
  align-items: center;
}

@media (min-width: 768px) {
  .about-statement {
    grid-template-columns: 1fr 1fr;
    gap: 80px;
  }
}

.about-visual {
  position: relative;
  height: 400px;
  border-radius: 4px;
  overflow: hidden;
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-secondary) 100%);
}

.about-visual-overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 32px;
  background: linear-gradient(transparent, rgba(10,22,40,0.9));
}

.about-visual-stat {
  color: var(--color-white);
}

.about-visual-stat .number {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--color-accent);
  display: block;
}

.about-visual-stat .label {
  font-size: 0.875rem;
  opacity: 0.8;
}

.about-text h2 {
  margin-bottom: 24px;
}

.about-text p {
  color: var(--color-gray-600);
  margin-bottom: 32px;
  line-height: 1.8;
}

/* ─── WHAT WE DO (TABS) ─────────────── */
.what-we-do {
  background: var(--color-primary);
  padding: 96px 0;
}

.wwd-layout {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0;
}

@media (min-width: 768px) {
  .wwd-layout {
    grid-template-columns: 280px 1fr;
    gap: 0;
  }
}

.wwd-tabs {
  display: flex;
  flex-direction: row;
  overflow-x: auto;
}

@media (min-width: 768px) {
  .wwd-tabs {
    flex-direction: column;
    overflow-x: visible;
    border-right: 1px solid rgba(255,255,255,0.1);
  }
}

.wwd-tab {
  padding: 20px 24px;
  background: none;
  border: none;
  color: rgba(255,255,255,0.5);
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 500;
  cursor: pointer;
  text-align: left;
  transition: all var(--transition-base);
  white-space: nowrap;
  position: relative;
  min-height: 48px;
}

@media (min-width: 768px) {
  .wwd-tab {
    padding: 28px 32px;
    font-size: 1.125rem;
  }
}

.wwd-tab::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 24px;
  right: 24px;
  height: 3px;
  background: var(--color-accent);
  transform: scaleX(0);
  transition: transform var(--transition-base);
}

@media (min-width: 768px) {
  .wwd-tab::after {
    top: 0;
    bottom: 0;
    left: auto;
    right: 0;
    width: 3px;
    height: auto;
    transform: scaleY(0);
  }
}

.wwd-tab.active {
  color: var(--color-white);
}

.wwd-tab.active::after {
  transform: scaleX(1);
}

@media (min-width: 768px) {
  .wwd-tab.active::after {
    transform: scaleY(1);
  }
}

.wwd-tab:hover {
  color: rgba(255,255,255,0.8);
}

.wwd-panels {
  position: relative;
  min-height: 250px;
}

.wwd-panel {
  display: none;
  padding: 32px 24px;
}

@media (min-width: 768px) {
  .wwd-panel {
    padding: 32px 48px;
  }
}

.wwd-panel.active {
  display: block;
  animation: panelFade 0.35s ease;
}

@keyframes panelFade {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

.wwd-panel h3 {
  color: var(--color-white);
  font-size: 1.75rem;
  margin-bottom: 20px;
}

.wwd-panel p {
  color: rgba(255,255,255,0.7);
  font-size: 1.0625rem;
  line-height: 1.8;
  margin-bottom: 32px;
  max-width: 560px;
}

.wwd-panel .service-list {
  margin-bottom: 32px;
}

.wwd-panel .service-list li {
  color: rgba(255,255,255,0.7);
  padding: 8px 0;
  padding-left: 20px;
  position: relative;
  font-size: 0.95rem;
}

.wwd-panel .service-list li::before {
  content: '';
  position: absolute;
  left: 0;
  top: 16px;
  width: 6px;
  height: 6px;
  background: var(--color-accent);
  border-radius: 50%;
}

.wwd-panel .btn-primary {
  margin-top: 8px;
}

/* ─── NEWSLETTER ─────────────────────── */
.newsletter {
  background: linear-gradient(135deg, var(--color-secondary) 0%, var(--color-primary) 100%);
  padding: 80px 0;
  text-align: center;
}

.newsletter h2 {
  color: var(--color-white);
  margin-bottom: 12px;
}

.newsletter p {
  color: rgba(255,255,255,0.7);
  margin: 0 auto 32px;
  max-width: 480px;
}

.newsletter-form {
  display: flex;
  flex-direction: column;
  gap: 12px;
  max-width: 440px;
  margin: 0 auto;
}

@media (min-width: 480px) {
  .newsletter-form {
    flex-direction: row;
  }
}

.newsletter-form input {
  flex: 1;
  padding: 14px 20px;
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: 2px;
  background: rgba(255,255,255,0.1);
  color: var(--color-white);
  font-family: var(--font-body);
  font-size: 0.9375rem;
  min-height: 48px;
}

.newsletter-form input::placeholder {
  color: rgba(255,255,255,0.5);
}

.newsletter-form input:focus {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

/* ─── COMMITMENT PILLARS ─────────────── */
.pillars-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}

@media (min-width: 768px) {
  .pillars-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .pillars-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

.pillar-card {
  padding: 32px;
  border: 1px solid var(--color-gray-200);
  border-radius: 4px;
  transition: all var(--transition-base);
}

.pillar-card:hover {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-md);
}

.pillar-icon {
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(197,165,90,0.1);
  border-radius: 8px;
  margin-bottom: 20px;
  color: var(--color-accent);
}

.pillar-card h3 {
  font-size: 1.125rem;
  margin-bottom: 12px;
}

.pillar-card p {
  color: var(--color-gray-500);
  font-size: 0.9375rem;
  line-height: 1.7;
  margin-bottom: 20px;
}

/* ─── SERVICE CATEGORIES GRID ────────── */
.services-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 32px;
}

@media (min-width: 768px) {
  .services-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .services-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.service-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: 4px;
  padding: 40px 32px;
  transition: all var(--transition-base);
  display: flex;
  flex-direction: column;
}

.service-card:hover {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.service-card-icon {
  width: 56px;
  height: 56px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, var(--color-primary), var(--color-secondary));
  border-radius: 8px;
  margin-bottom: 24px;
  color: var(--color-accent);
}

.service-card h3 {
  font-size: 1.25rem;
  margin-bottom: 16px;
}

.service-card p {
  color: var(--color-gray-500);
  font-size: 0.9375rem;
  line-height: 1.7;
  margin-bottom: 24px;
  flex: 1;
}

/* ─── CAPABILITIES GRID ──────────────── */
.capabilities-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}

@media (min-width: 768px) {
  .capabilities-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .capabilities-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.capability-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: 4px;
  padding: 32px;
  transition: all var(--transition-base);
}

.capability-card:hover {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-md);
}

.capability-card h4 {
  font-family: var(--font-heading);
  font-size: 1.125rem;
  margin-bottom: 12px;
  color: var(--color-primary);
}

.capability-card p {
  color: var(--color-gray-500);
  font-size: 0.9375rem;
  line-height: 1.7;
}

.capability-card-accent {
  width: 40px;
  height: 3px;
  background: var(--color-accent);
  margin-bottom: 20px;
}

/* ─── FEATURED TOPICS ────────────────── */
.topics-list {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.topic-tag {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 24px;
  border: 1px solid var(--color-gray-200);
  border-radius: 4px;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-primary);
  transition: all var(--transition-base);
  cursor: pointer;
}

.topic-tag:hover {
  border-color: var(--color-accent);
  background: rgba(197,165,90,0.05);
  color: var(--color-accent);
}

/* ─── PARTNERSHIP HIGHLIGHT ──────────── */
.partnership {
  display: grid;
  grid-template-columns: 1fr;
  gap: 48px;
  align-items: center;
}

@media (min-width: 768px) {
  .partnership {
    grid-template-columns: 1fr 1fr;
    gap: 80px;
  }
}

.partnership-visual {
  height: 360px;
  background: linear-gradient(135deg, var(--color-primary), var(--color-secondary));
  border-radius: 4px;
  position: relative;
  overflow: hidden;
}

.partnership-stats {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  display: grid;
  grid-template-columns: 1fr 1fr;
}

.partnership-stat {
  padding: 24px;
  background: rgba(10,22,40,0.8);
  text-align: center;
}

.partnership-stat .number {
  font-family: var(--font-heading);
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--color-accent);
  display: block;
}

.partnership-stat .label {
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.7);
}

/* ─── TESTIMONIAL ────────────────────── */
.testimonial-block {
  background: var(--color-gray-50);
  border-left: 4px solid var(--color-accent);
  padding: 40px;
  border-radius: 0 4px 4px 0;
}

.testimonial-block blockquote {
  font-size: 1.125rem;
  line-height: 1.8;
  color: var(--color-gray-700);
  margin-bottom: 20px;
  font-style: italic;
}

.testimonial-block cite {
  font-style: normal;
  font-weight: 600;
  color: var(--color-primary);
  font-size: 0.9375rem;
}

/* ─── CAROUSEL ────────────────────────── */
.carousel-container {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform var(--transition-slow);
}

.carousel-slide {
  min-width: 100%;
  padding: 0 12px;
}

@media (min-width: 768px) {
  .carousel-slide { min-width: 50%; }
}

@media (min-width: 1024px) {
  .carousel-slide { min-width: 33.333%; }
}

.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-top: 32px;
}

.carousel-btn {
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 2px solid var(--color-gray-200);
  border-radius: 50%;
  background: var(--color-white);
  cursor: pointer;
  transition: all var(--transition-fast);
  color: var(--color-primary);
}

.carousel-btn:hover {
  border-color: var(--color-accent);
  color: var(--color-accent);
}

.carousel-dots {
  display: flex;
  gap: 8px;
}

.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-gray-300);
  border: none;
  cursor: pointer;
  transition: all var(--transition-fast);
  padding: 0;
}

.carousel-dot.active {
  background: var(--color-accent);
  width: 24px;
  border-radius: 4px;
}

/* ─── RELATED SERVICES ───────────────── */
.related-services-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 20px;
}

@media (min-width: 768px) {
  .related-services-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

.related-service-link {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 24px;
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: 4px;
  transition: all var(--transition-base);
}

.related-service-link:hover {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-md);
}

.related-service-link span {
  font-weight: 600;
  color: var(--color-primary);
}

.related-service-link .arrow-icon {
  color: var(--color-accent);
  transition: transform var(--transition-fast);
}

.related-service-link:hover .arrow-icon {
  transform: translateX(4px);
}

/* ─── PROPERTY TYPES CTA ─────────────── */
.property-types-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}

@media (min-width: 768px) {
  .property-types-grid {
    grid-template-columns: repeat(5, 1fr);
  }
}

.property-type-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  padding: 24px 16px;
  border: 1px solid var(--color-gray-200);
  border-radius: 4px;
  transition: all var(--transition-base);
  text-align: center;
  cursor: pointer;
}

.property-type-card:hover {
  border-color: var(--color-accent);
  background: rgba(197,165,90,0.03);
}

.property-type-icon {
  width: 44px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-secondary);
}

.property-type-card span {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-primary);
}

/* ─── DEAL FLOW CTA ──────────────────── */
.deal-flow-cta {
  background: linear-gradient(135deg, var(--color-primary), var(--color-secondary));
  border-radius: 4px;
  padding: 56px 48px;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 24px;
}

@media (min-width: 768px) {
  .deal-flow-cta {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }
}

.deal-flow-cta h3 {
  color: var(--color-white);
  font-size: 1.5rem;
}

.deal-flow-cta p {
  color: rgba(255,255,255,0.7);
  max-width: 480px;
}

/* ─── FOOTER ──────────────────────────── */
.site-footer {
  background: var(--color-gray-900);
  color: rgba(255,255,255,0.7);
  padding: 64px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 40px;
  margin-bottom: 48px;
}

@media (min-width: 768px) {
  .footer-grid {
    grid-template-columns: 2fr 1fr 1fr 1fr;
  }
}

.footer-brand .logo {
  margin-bottom: 16px;
  font-size: 1.125rem;
}

.footer-brand p {
  font-size: 0.875rem;
  line-height: 1.7;
  max-width: 300px;
}

.footer-col h4 {
  font-family: var(--font-body);
  font-size: 0.8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-white);
  margin-bottom: 20px;
}

.footer-col a {
  display: block;
  padding: 6px 0;
  font-size: 0.875rem;
  color: rgba(255,255,255,0.6);
  transition: color var(--transition-fast);
}

.footer-col a:hover {
  color: var(--color-accent);
}

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 24px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  align-items: center;
  text-align: center;
}

@media (min-width: 768px) {
  .footer-bottom {
    flex-direction: row;
    justify-content: space-between;
    text-align: left;
  }
}

.footer-bottom p {
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.4);
}

.footer-legal {
  display: flex;
  gap: 24px;
  flex-wrap: wrap;
}

.footer-legal a {
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.4);
  transition: color var(--transition-fast);
}

.footer-legal a:hover {
  color: var(--color-accent);
}

/* ─── UTILITIES ──────────────────────── */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  border: 0;
}

.text-accent { color: var(--color-accent); }
.text-white { color: var(--color-white); }
.bg-white { background: var(--color-white); }

@media (prefers-reduced-motion: reduce) {
  *,*::before,*::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
  html { scroll-behavior: auto; }
}

/* ─── SKIP LINK ──────────────────────── */
.skip-link {
  position: absolute;
  top: -100px;
  left: 16px;
  background: var(--color-accent);
  color: var(--color-primary);
  padding: 12px 24px;
  font-weight: 600;
  z-index: 10000;
  border-radius: 0 0 4px 4px;
  transition: top var(--transition-fast);
}

.skip-link:focus {
  top: 0;
}

raw_arguments.content:
@import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@400;500;600;700&family=Inter:wght@300;400;500;600;700&display=swap');

:root {
  --color-primary: #0A1628;
  --color-primary-light: #132240;
  --color-secondary: #003F2D;
  --color-accent: #C5A55A;
  --color-accent-hover: #B8963F;
  --color-white: #FFFFFF;
  --color-gray-50: #F8FAFC;
  --color-gray-100: #F1F5F9;
  --color-gray-200: #E2E8F0;
  --color-gray-300: #CBD5E1;
  --color-gray-400: #94A3B8;
  --color-gray-500: #64748B;
  --color-gray-600: #475569;
  --color-gray-700: #334155;
  --color-gray-800: #1E293B;
  --color-gray-900: #0F172A;
  --color-teal: #0D9488;
  --color-teal-dark: #0F766E;

  --font-heading: 'Cinzel', Georgia, serif;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;

  --max-width: 1280px;
  --header-height: 80px;

  --shadow-sm: 0 1px 2px rgba(10,22,40,0.05);
  --shadow-md: 0 4px 12px rgba(10,22,40,0.08);
  --shadow-lg: 0 8px 30px rgba(10,22,40,0.12);
  --shadow-xl: 0 20px 50px rgba(10,22,40,0.15);

  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;
}

*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-body);
  color: var(--color-gray-800);
  background: var(--color-white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

ul, ol { list-style: none; }

h1, h2, h3, h4, h5 {
  font-family: var(--font-heading);
  color: var(--color-primary);
  line-height: 1.2;
  font-weight: 600;
}

h1 { font-size: clamp(2rem, 4vw, 3.25rem); }
h2 { font-size: clamp(1.5rem, 3vw, 2.5rem); }
h3 { font-size: clamp(1.125rem, 2vw, 1.5rem); }
h4 { font-size: 1.125rem; }

p { max-width: 72ch; }

.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

@media (min-width: 768px) {
  .container { padding: 0 40px; }
}

@media (min-width: 1024px) {
  .container { padding: 0 48px; }
}

/* ─── BUTTONS ──────────────────────────────── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 32px;
  font-family: var(--font-body);
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  border: none;
  border-radius: 2px;
  cursor: pointer;
  transition: all var(--transition-base);
  white-space: nowrap;
  min-height: 48px;
}

.btn-primary {
  background: var(--color-accent);
  color: var(--color-primary);
}
.btn-primary:hover {
  background: var(--color-accent-hover);
  box-shadow: var(--shadow-md);
}

.btn-outline {
  background: transparent;
  color: var(--color-white);
  border: 2px solid var(--color-white);
}
.btn-outline:hover {
  background: var(--color-white);
  color: var(--color-primary);
}

.btn-outline-dark {
  background: transparent;
  color: var(--color-primary);
  border: 2px solid var(--color-primary);
}
.btn-outline-dark:hover {
  background: var(--color-primary);
  color: var(--color-white);
}

.btn-ghost {
  background: transparent;
  color: var(--color-accent);
  padding: 8px 0;
  letter-spacing: 0.02em;
}
.btn-ghost:hover { color: var(--color-accent-hover); }
.btn-ghost .arrow { transition: transform var(--transition-fast); }
.btn-ghost:hover .arrow { transform: translateX(4px); }

/* ─── HEADER ──────────────────────────────── */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: var(--color-primary);
  height: var(--header-height);
  transition: background var(--transition-base), box-shadow var(--transition-base);
}

.site-header.scrolled {
  background: rgba(10,22,40,0.97);
  box-shadow: var(--shadow-lg);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

@media (min-width: 768px) {
  .header-inner { padding: 0 40px; }
}

.logo {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-white);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  display: flex;
  align-items: center;
  gap: 10px;
}

.logo-icon {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.logo-icon svg {
  width: 100%;
  height: 100%;
}

/* ── Desktop Nav ── */
.main-nav {
  display: none;
  align-items: center;
  gap: 0;
  height: 100%;
}

@media (min-width: 1024px) {
  .main-nav { display: flex; }
}

.nav-link {
  display: flex;
  align-items: center;
  gap: 4px;
  height: 100%;
  padding: 0 20px;
  color: rgba(255,255,255,0.85);
  font-size: 0.9rem;
  font-weight: 500;
  transition: color var(--transition-fast);
  cursor: pointer;
  position: relative;
}

.nav-link:hover,
.nav-link.active {
  color: var(--color-white);
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 20px;
  right: 20px;
  height: 3px;
  background: var(--color-accent);
  transform: scaleX(0);
  transition: transform var(--transition-base);
}

.nav-link:hover::after,
.nav-link.active::after {
  transform: scaleX(1);
}

.nav-link .chevron {
  width: 12px;
  height: 12px;
  transition: transform var(--transition-fast);
}

.nav-link:hover .chevron,
.nav-link.active .chevron {
  transform: rotate(180deg);
}

/* ── Mega Menu ── */
.mega-menu {
  position: absolute;
  top: var(--header-height);
  left: 0;
  right: 0;
  background: var(--color-white);
  box-shadow: var(--shadow-xl);
  opacity: 0;
  visibility: hidden;
  transform: translateY(-8px);
  transition: opacity var(--transition-base), visibility var(--transition-base), transform var(--transition-base);
  z-index: 999;
}

.mega-menu.open {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.mega-menu-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 48px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
}

.mega-menu-col h4 {
  font-family: var(--font-body);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--color-gray-400);
  margin-bottom: 20px;
}

.mega-menu-links {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.mega-menu-links a {
  display: block;
  padding: 10px 16px;
  color: var(--color-gray-700);
  font-size: 0.95rem;
  font-weight: 500;
  border-radius: 6px;
  transition: all var(--transition-fast);
}

.mega-menu-links a:hover {
  background: var(--color-gray-50);
  color: var(--color-secondary);
}

/* ── Mobile Nav ── */
.mobile-toggle {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
  background: none;
  border: none;
  cursor: pointer;
  min-width: 44px;
  min-height: 44px;
  align-items: center;
  justify-content: center;
}

@media (min-width: 1024px) {
  .mobile-toggle { display: none; }
}

.mobile-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--color-white);
  border-radius: 2px;
  transition: all var(--transition-base);
}

.mobile-toggle.active span:nth-child(1) {
  transform: translateY(7px) rotate(45deg);
}
.mobile-toggle.active span:nth-child(2) {
  opacity: 0;
}
.mobile-toggle.active span:nth-child(3) {
  transform: translateY(-7px) rotate(-45deg);
}

.mobile-nav {
  position: fixed;
  top: var(--header-height);
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--color-primary);
  z-index: 998;
  overflow-y: auto;
  transform: translateX(100%);
  transition: transform var(--transition-slow);
}

.mobile-nav.open {
  transform: translateX(0);
}

.mobile-nav-links {
  padding: 24px;
}

.mobile-nav-link {
  display: block;
  padding: 16px 0;
  color: rgba(255,255,255,0.85);
  font-size: 1.1rem;
  font-weight: 500;
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

.mobile-accordion-btn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 16px 0;
  background: none;
  border: none;
  border-bottom: 1px solid rgba(255,255,255,0.1);
  color: rgba(255,255,255,0.85);
  font-family: var(--font-body);
  font-size: 1.1rem;
  font-weight: 500;
  cursor: pointer;
  min-height: 56px;
}

.mobile-accordion-btn .chevron-mobile {
  width: 16px;
  height: 16px;
  transition: transform var(--transition-fast);
  color: var(--color-accent);
}

.mobile-accordion-btn.active .chevron-mobile {
  transform: rotate(180deg);
}

.mobile-accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow);
}

.mobile-accordion-content.open {
  max-height: 600px;
}

.mobile-accordion-content a {
  display: block;
  padding: 12px 24px;
  color: rgba(255,255,255,0.65);
  font-size: 0.95rem;
  border-bottom: 1px solid rgba(255,255,255,0.05);
  transition: color var(--transition-fast);
}

.mobile-accordion-content a:hover {
  color: var(--color-accent);
}

.mobile-accordion-label {
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--color-gray-400);
  padding: 16px 24px 8px;
}

/* ─── HERO ──────────────────────────────── */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-light) 50%, var(--color-secondary) 100%);
  overflow: hidden;
  padding-top: var(--header-height);
}

.hero-bg {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
  opacity: 0.25;
}

.hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(10,22,40,0.85) 0%, rgba(0,63,45,0.7) 100%);
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 680px;
  padding: 80px 0;
}

.hero-eyebrow {
  font-family: var(--font-body);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  color: var(--color-accent);
  margin-bottom: 24px;
}

.hero h1 {
  color: var(--color-white);
  margin-bottom: 24px;
  font-size: clamp(2.25rem, 5vw, 3.5rem);
}

.hero p {
  color: rgba(255,255,255,0.8);
  font-size: 1.125rem;
  line-height: 1.7;
  margin-bottom: 40px;
  max-width: 540px;
}

.hero-pattern {
  position: absolute;
  right: -100px;
  bottom: -100px;
  width: 500px;
  height: 500px;
  border: 1px solid rgba(197,165,90,0.1);
  border-radius: 50%;
}

.hero-pattern::before {
  content: '';
  position: absolute;
  top: 40px;
  left: 40px;
  right: 40px;
  bottom: 40px;
  border: 1px solid rgba(197,165,90,0.07);
  border-radius: 50%;
}

/* ── Page Hero (smaller variant) ── */
.hero-page {
  min-height: 50vh;
  padding-top: var(--header-height);
}

.hero-page .hero-content {
  padding: 60px 0;
}

/* ─── SECTIONS ──────────────────────────── */
.section {
  padding: 96px 0;
}

.section-sm {
  padding: 64px 0;
}

.section-dark {
  background: var(--color-primary);
  color: var(--color-white);
}

.section-dark h2,
.section-dark h3,
.section-dark h4 {
  color: var(--color-white);
}

.section-light {
  background: var(--color-gray-50);
}

.section-header {
  margin-bottom: 56px;
}

.section-header h2 {
  margin-bottom: 16px;
}

.section-header p {
  color: var(--color-gray-500);
  font-size: 1.0625rem;
  line-height: 1.7;
}

.section-eyebrow {
  font-family: var(--font-body);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  color: var(--color-accent);
  margin-bottom: 12px;
}

/* ─── FEATURED INSIGHTS ──────────────── */
.insights-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}

@media (min-width: 768px) {
  .insights-grid { grid-template-columns: repeat(3, 1fr); }
}

.insight-card {
  background: var(--color-white);
  border-radius: 4px;
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-base);
}

.insight-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.insight-card-img {
  height: 200px;
  background: linear-gradient(135deg, var(--color-primary-light), var(--color-secondary));
  position: relative;
  overflow: hidden;
}

.insight-card-img::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(45deg, rgba(197,165,90,0.15), transparent);
}

.insight-card-body {
  padding: 24px;
}

.insight-tag {
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-teal);
  margin-bottom: 12px;
}

.insight-card-body h3 {
  font-size: 1.0625rem;
  line-height: 1.4;
  margin-bottom: 12px;
}

.insight-date {
  font-size: 0.8125rem;
  color: var(--color-gray-400);
}

/* ─── ANNOUNCEMENT BANNER ────────────── */
.announcement-banner {
  background: var(--color-secondary);
  padding: 20px 0;
}

.announcement-inner {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 24px;
  flex-wrap: wrap;
  text-align: center;
}

.announcement-inner p {
  color: var(--color-white);
  font-size: 1rem;
  font-weight: 500;
}

.announcement-inner .btn-ghost {
  color: var(--color-accent);
}

/* ─── ABOUT STATEMENT ────────────────── */
.about-statement {
  display: grid;
  grid-template-columns: 1fr;
  gap: 48px;
  align-items: center;
}

@media (min-width: 768px) {
  .about-statement {
    grid-template-columns: 1fr 1fr;
    gap: 80px;
  }
}

